//! Op-level parity with numpy, scipy.ndimage and nibabel, on the small cases generated by
//! `tests/data/make_test_data.py`. Every comparison is bit-exact unless a comment says otherwise.

mod common;

use common::{Reference, assert_bits_eq_f32, assert_bits_eq_f64};
use larmor_volume::ndarray::{Array3, ArrayD, Ix3};
use larmor_volume::{
    Affine, ExtendMode, Interpolation, Nifti, Sigma, Volume, Voxel, VoxelData, affine_transform,
    binary_fill_holes, gaussian_filter, gaussian_kernel1d, io_orientation, label, largest_component,
    mean_f32, pairwise_sum_f32, pairwise_sum_f64, quantiles_linear, vox2out_vox,
};
use safetensors::Dtype;

fn formula_values(n: usize) -> Vec<f32> {
    (0..n as i64).map(|i| (((i * 7919) % 10007) as f64 / 37.0 - 100.0) as f32).collect()
}

#[test]
fn pairwise_sums_and_means_match_numpy() {
    let r = Reference::load("stats");
    for (name, case) in r.cases_of("sum") {
        let x = r.f32s(&format!("{name}/f32"));
        assert_bits_eq_f32([pairwise_sum_f32(&x)], r.f32s(&format!("{name}/f32_expected")), &name);
        let x = r.f64s(&format!("{name}/f64"));
        assert_bits_eq_f64([pairwise_sum_f64(&x)], r.f64s(&format!("{name}/f64_expected")), &name);
        assert!(case["n"].as_u64().unwrap() as usize == x.len());
    }
    for (name, case) in r.cases_of("formula") {
        let x = formula_values(case["n"].as_u64().unwrap() as usize);
        assert_bits_eq_f32([pairwise_sum_f32(&x)], r.f32s(&format!("{name}/f32_expected")), &name);
        assert_bits_eq_f32([mean_f32(&x)], r.f32s(&format!("{name}/mean_expected")), &name);
    }
    let vol = Reference::array3(r.f32_array("mean3d/x"));
    assert_bits_eq_f32([mean_f32(vol.as_slice().unwrap())], r.f32s("mean3d/expected"), "mean3d");
}

#[test]
fn quantiles_match_numpy_linear_method() {
    let r = Reference::load("stats");
    for (name, _) in r.cases_of("quantile") {
        let mut values = r.f32s(&format!("{name}/values"));
        let qs = r.f64s(&format!("{name}/qs"));
        let got = quantiles_linear(&mut values, &qs).unwrap();
        assert_bits_eq_f64(got, r.f64s(&format!("{name}/expected")), &name);
    }
}

#[test]
fn gaussian_kernels_match_scipy() {
    let r = Reference::load("filter");
    for (name, case) in r.cases_of("kernel") {
        let key = format!("{name}/sigma");
        let sigma = match r.dtype(&key) {
            Dtype::F32 => Sigma::F32(r.f32s(&key)[0]),
            _ => Sigma::F64(r.f64s(&key)[0]),
        };
        let radius = sigma.radius(4.0);
        assert_eq!(radius as u64, case["radius"].as_u64().unwrap(), "{name} radius");
        assert_bits_eq_f64(gaussian_kernel1d(sigma, radius), r.f64s(&format!("{name}/expected")), &name);
    }
}

#[test]
fn gaussian_filter_matches_scipy() {
    let r = Reference::load("filter");
    for (name, case) in r.cases_of("gaussian") {
        let x = Reference::array3(r.f32_array(&format!("{name}/x")));
        let key = format!("{name}/sigmas");
        let sigmas: [Sigma; 3] = match r.dtype(&key) {
            Dtype::F32 => r.f32s(&key).iter().map(|&s| Sigma::F32(s)).collect::<Vec<_>>().try_into().unwrap(),
            _ => r.f64s(&key).iter().map(|&s| Sigma::F64(s)).collect::<Vec<_>>().try_into().unwrap(),
        };
        let mode = match case["mode"].as_str().unwrap() {
            "reflect" => ExtendMode::Reflect,
            "nearest" => ExtendMode::Nearest,
            other => panic!("mode {other}"),
        };
        let got = gaussian_filter(&x, sigmas, mode, 4.0);
        let expected = r.f32_array(&format!("{name}/expected"));
        assert_eq!(got.shape(), expected.shape());
        assert_bits_eq_f32(got.iter().copied(), expected.iter().copied(), &name);
    }
}

fn check_affine_transform<T: Voxel + PartialEq + std::fmt::Debug>(
    name: &str,
    x: ArrayD<T>,
    expected: ArrayD<T>,
    r: &Reference,
    order: Interpolation,
) {
    let x = Reference::array3(x);
    let shape = expected.shape();
    let got = affine_transform(
        x.view(),
        r.matrix3(&format!("{name}/matrix")),
        r.vec3(&format!("{name}/offset")),
        [shape[0], shape[1], shape[2]],
        order,
        0.0,
    );
    let mismatches =
        got.iter().zip(expected.iter()).filter(|(a, b)| a.to_f64().to_bits() != b.to_f64().to_bits()).count();
    assert_eq!(mismatches, 0, "{name}: {mismatches} of {} voxels differ", got.len());
}

#[test]
fn affine_transform_matches_scipy() {
    let r = Reference::load("resample");
    for (name, case) in r.cases_of("affine_transform") {
        let order = Interpolation::from_order(case["order"].as_i64().unwrap()).unwrap();
        let (x, e) = (format!("{name}/x"), format!("{name}/expected"));
        match r.dtype(&x) {
            Dtype::F32 => check_affine_transform(&name, r.f32_array(&x), r.f32_array(&e), &r, order),
            Dtype::F64 => check_affine_transform(&name, r.f64_array(&x), r.f64_array(&e), &r, order),
            Dtype::U8 => check_affine_transform(&name, r.u8_array(&x), r.u8_array(&e), &r, order),
            Dtype::I16 => check_affine_transform(&name, r.i16_array(&x), r.i16_array(&e), &r, order),
            Dtype::U16 => check_affine_transform(&name, r.u16_array(&x), r.u16_array(&e), &r, order),
            Dtype::I32 => check_affine_transform(&name, r.i32_array(&x), r.i32_array(&e), &r, order),
            other => panic!("{name}: dtype {other:?}"),
        }
    }
}

#[test]
fn vox2out_vox_matches_nibabel() {
    let r = Reference::load("resample");
    for (name, _) in r.cases_of("vox2out_vox") {
        let shape: [usize; 3] = r
            .i64s(&format!("{name}/shape"))
            .iter()
            .map(|&s| s as usize)
            .collect::<Vec<_>>()
            .try_into()
            .unwrap();
        let (out_shape, out_affine) = vox2out_vox(shape, &r.affine(&format!("{name}/affine")), [2.0; 3]);
        let expected: Vec<usize> = r.i64s(&format!("{name}/out_shape")).iter().map(|&s| s as usize).collect();
        assert_eq!(out_shape.to_vec(), expected, "{name} shape");
        assert_eq!(out_affine, r.affine(&format!("{name}/out_affine")), "{name} affine");
    }
}

#[test]
fn resample_from_to_matches_nibabel() {
    let r = Reference::load("resample");
    for (name, case) in r.cases_of("resample_from_to") {
        let order = Interpolation::from_order(case["order"].as_i64().unwrap()).unwrap();
        let to_shape: [usize; 3] = case["to_shape"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as usize)
            .collect::<Vec<_>>()
            .try_into()
            .unwrap();
        let from_affine = r.affine(&format!("{name}/from_affine"));
        let to_affine = r.affine(&format!("{name}/to_affine"));
        let zooms = r.f32s(&format!("{name}/zooms"));
        let x = format!("{name}/x");
        let e = format!("{name}/expected");
        match r.dtype(&x) {
            Dtype::F32 => {
                let vol = Volume::new(Reference::array3(r.f32_array(&x)), from_affine);
                let out = vol.resample_to(to_shape, &to_affine, order).unwrap();
                assert_bits_eq_f32(out.data.iter().copied(), r.f32s(&e), &name);
                assert_eq!(out.zooms.to_vec(), zooms, "{name} zooms");
            }
            Dtype::U8 => {
                let vol = Volume::new(Reference::array3(r.u8_array(&x)), from_affine);
                let out = vol.resample_to(to_shape, &to_affine, order).unwrap();
                assert_eq!(out.data.iter().copied().collect::<Vec<_>>(), r.u8s(&e), "{name}");
                assert_eq!(out.zooms.to_vec(), zooms, "{name} zooms");
            }
            other => panic!("{name}: dtype {other:?}"),
        }
    }
}

#[test]
fn orientation_and_canonical_match_nibabel() {
    let r = Reference::load("orientation");
    let data = Reference::array3(r.i16_array("data"));
    for (name, case) in r.cases_of("orientation") {
        let affine = r.affine(&format!("{name}/affine"));
        let ornt = io_orientation(&affine).unwrap();
        let expected = r.i64s(&format!("{name}/ornt"));
        let got: Vec<i64> =
            ornt.0.iter().flat_map(|a| [a.axis as i64, if a.flip { -1 } else { 1 }]).collect();
        assert_eq!(got, expected, "{name} ornt");
        assert_eq!(ornt.axcodes(), case["axcodes"].as_str().unwrap(), "{name} axcodes");

        let canonical = Volume::new(data.clone(), affine).as_closest_canonical().unwrap();
        assert_eq!(canonical.affine, r.affine(&format!("{name}/canonical_affine")), "{name} affine");
        let expected_data = Reference::array3(r.i16_array(&format!("{name}/canonical_data")));
        assert_eq!(canonical.data, expected_data, "{name} data");
        assert_eq!(canonical.zooms.to_vec(), r.f32s(&format!("{name}/canonical_zooms")), "{name} zooms");
    }
}

#[test]
fn morphology_matches_scipy() {
    let r = Reference::load("morphology");
    for (name, _) in r.cases_of("morphology") {
        let mask = r.bools(&format!("{name}/mask"));
        let (labels, count) = label(mask.view());
        assert_eq!(count as i64, r.i64s(&format!("{name}/count"))[0], "{name} count");
        assert_eq!(
            labels.iter().copied().collect::<Vec<_>>(),
            r.u32s(&format!("{name}/labels")),
            "{name} labels"
        );
        assert_eq!(largest_component(mask.view()), r.bools(&format!("{name}/largest")), "{name} largest");
        assert_eq!(binary_fill_holes(mask.view()), r.bools(&format!("{name}/filled")), "{name} filled");
    }
}

/// The stored array of a NIfTI case in C order, whatever its dtype.
fn voxels_as_f64(data: &VoxelData) -> Vec<f64> {
    data.to_f64().as_standard_layout().iter().copied().collect()
}

#[test]
fn nifti_headers_and_data_match_nibabel() {
    let r = Reference::load("nifti");
    for (name, case) in r.cases_of("nifti") {
        for source in ["bytes", "gz"] {
            let what = format!("{name} ({source})");
            let img = Nifti::from_bytes(&r.u8s(&format!("{name}/{source}")))
                .unwrap_or_else(|e| panic!("{what}: {e}"));
            let shape: Vec<usize> =
                case["shape"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
            assert_eq!(img.shape(), shape.as_slice(), "{what} shape");
            assert_eq!(img.data.dtype().name(), case["dtype"].as_str().unwrap(), "{what} dtype");
            assert_eq!(img.affine().unwrap(), r.affine(&format!("{name}/affine")), "{what} affine");
            assert_eq!(img.zooms(), r.f32s(&format!("{name}/zooms")), "{what} zooms");

            let fdata = img.fdata_f32();
            assert_bits_eq_f32(
                fdata.as_standard_layout().iter().copied(),
                r.f32s(&format!("{name}/fdata")),
                &what,
            );

            let dataobj = img.dataobj();
            assert_eq!(
                dataobj.dtype().name(),
                case["dataobj_dtype"].as_str().unwrap(),
                "{what} dataobj dtype"
            );
            let key = format!("{name}/dataobj");
            let expected: Vec<f64> = match r.dtype(&key) {
                Dtype::F64 => r.f64s(&key),
                Dtype::F32 => r.f32s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::U8 => r.u8s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::I8 => r.i8s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::I16 => r.i16s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::U16 => r.u16s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::I32 => r.i32s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::U32 => r.u32s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::I64 => r.i64s(&key).iter().map(|&v| v as f64).collect(),
                Dtype::U64 => r.u64s(&key).iter().map(|&v| v as f64).collect(),
                other => panic!("{what}: dtype {other:?}"),
            };
            assert_bits_eq_f64(voxels_as_f64(&dataobj), expected, &what);
        }
    }
}

#[test]
fn nifti_write_round_trips_through_reader() {
    let dir = std::env::temp_dir().join(format!("larmor-volume-test-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let data = Array3::from_shape_fn([5, 4, 3], |(i, j, k)| (i * 12 + j * 3 + k) as u16).into_dyn();
    let affine =
        Affine::from_matvec([[-1.5, 0.0, 0.0], [0.0, 0.0, 2.0], [0.0, 1.25, 0.0]], [30.0, -40.0, 12.0]);
    let img = Nifti::new(VoxelData::U16(data.clone()), &affine);
    for file in ["mask.nii", "mask.nii.gz"] {
        let path = dir.join(file);
        img.write(&path).unwrap();
        let back = Nifti::read(&path).unwrap();
        assert_eq!(back.data, VoxelData::U16(data.clone()), "{file}");
        assert_eq!(back.affine().unwrap(), affine, "{file}");
        assert_eq!(back.header.sform_code, 2);
        assert_eq!(back.header.qform_code, 0);
        let as_3d = back.data.to_f32().into_dimensionality::<Ix3>().unwrap();
        assert_eq!(as_3d[[4, 3, 2]], 59.0);
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn affine_products_inverses_and_points_match_numpy() {
    let r = Reference::load("affine");
    for (name, _) in r.cases_of("affine") {
        let a = r.affine(&format!("{name}/a"));
        let b = r.affine(&format!("{name}/b"));
        let flat = |m: Affine| m.0.into_iter().flatten().collect::<Vec<_>>();
        assert_bits_eq_f64(
            flat(a.inverse().unwrap()),
            r.f64s(&format!("{name}/inv")),
            &format!("{name} inv"),
        );
        assert_bits_eq_f64(flat(a.dot(&b)), r.f64s(&format!("{name}/dot")), &format!("{name} dot"));
        let points: Vec<[f64; 3]> =
            r.f64s(&format!("{name}/points")).chunks(3).map(|c| [c[0], c[1], c[2]]).collect();
        let many: Vec<f64> = a.apply_many(&points).into_iter().flatten().collect();
        assert_bits_eq_f64(many, r.f64s(&format!("{name}/apply_many")), &format!("{name} apply_many"));
        assert_bits_eq_f64(
            a.apply(points[0]),
            r.f64s(&format!("{name}/apply_one")),
            &format!("{name} apply_one"),
        );
        assert_bits_eq_f64(
            a.voxel_sizes(),
            r.f64s(&format!("{name}/voxel_sizes")),
            &format!("{name} voxel_sizes"),
        );
    }
}

#[test]
fn with_data_keeps_the_header_geometry() {
    let r = Reference::load("nifti");
    for case in ["n_qform_qfac_neg", "n_sform_wins", "n_base_affine"] {
        let img = Nifti::from_bytes(&r.u8s(&format!("{case}/bytes"))).unwrap();
        let labels = img.data.to_f32().mapv(|v| (v.abs() as u32 % 4) as u8);
        let back = Nifti::from_bytes(&img.with_data(VoxelData::U8(labels.clone())).to_bytes()).unwrap();
        assert_eq!(back.affine().unwrap(), img.affine().unwrap(), "{case}");
        assert_eq!(
            (back.header.sform_code, back.header.qform_code),
            (img.header.sform_code, img.header.qform_code)
        );
        assert_eq!(back.zooms(), img.zooms(), "{case}");
        assert_eq!(back.data, VoxelData::U8(labels), "{case}");
        assert_eq!(back.header.scaling(), None, "{case}");
    }
}
